// Figures. b/d = birth and death years CE; bc/dc mark an approximate year.
// dah = death year AH where commonly given. places run in order of the life.
// Dates are from general reference works and need checking before publication.

const FIGURES = [
  // 610–661
  { id: "ali", name: "Ali ibn Abi Talib", short: "Ali ibn Abi Talib", ar: "علي بن أبي طالب", b: 600, bc: true, d: 661, dah: 40, lane: "law", places: ["mecca", "medina", "kufa"],
    text: "Cousin and son-in-law of the Prophet, fourth caliph (656–661) and, for Shi’i Muslims, the first Imam. Sunni and Shi’i traditions alike cite his rulings and sermons. He was killed in Kufa during the first civil war.",
    works: [["Nahj al-balagha", "The peak of eloquence: sermons and letters attributed to him, compiled c. 1000"]] },
  { id: "aisha", name: "Aisha bint Abi Bakr", short: "Aisha", ar: "عائشة بنت أبي بكر", b: 614, bc: true, d: 678, dah: 58, lane: "hadith", places: ["mecca", "medina"],
    text: "Wife of the Prophet and daughter of Abu Bakr. One of the most prolific transmitters of hadith, she was consulted on law and on the Prophet’s practice, and corrected reports from other Companions that she judged mistaken." },
  { id: "ibn-abbas", name: "Abd Allah ibn Abbas", short: "Ibn Abbas", ar: "عبد الله بن عباس", b: 619, bc: true, d: 687, dah: 68, lane: "quran", places: ["mecca", "medina", "taif"],
    text: "Cousin of the Prophet, remembered as “the interpreter of the Qur’an”. His explanations of words and verses, passed on by his students in Mecca, are a foundation of later commentary." },

  // 661–750
  { id: "hasan-basri", name: "al-Hasan al-Basri", short: "al-Hasan al-Basri", ar: "الحسن البصري", b: 642, d: 728, dah: 110, lane: "sufism", also: ["theology"], places: ["medina", "basra"],
    text: "Preacher, ascetic and scholar of Basra. His sermons on piety and accountability made him a model for later Sufis, and theologians of several schools claimed him as a forerunner. A letter on human responsibility attributed to him is an early document of the free will debate." },
  { id: "abu-hanifa", name: "Abu Hanifa al-Nu’man", short: "Abu Hanifa", ar: "أبو حنيفة النعمان", b: 699, d: 767, dah: 150, lane: "law", schools: ["Hanafi"], places: ["kufa", "baghdad"], teachers: ["jafar"],
    text: "Jurist of Kufa whose reasoned method, including analogy, became the basis of the Hanafi school. It later prevailed in the Ottoman lands and in Central and South Asia. His views reach us mainly through his students Abu Yusuf and al-Shaybani.",
    works: [["al-Fiqh al-akbar", "The greater understanding, a creed attributed to him"]] },
  { id: "wasil", name: "Wasil ibn Ata", short: "Wasil ibn Ata", ar: "واصل بن عطاء", b: 700, d: 748, dah: 131, lane: "theology", schools: ["Mu’tazili"], places: ["medina", "basra"], teachers: ["hasan-basri"],
    text: "Basran theologian regarded as the founder of the Mu’tazila. Tradition says he left al-Hasan al-Basri’s circle over the grave sinner, whom he placed in an “intermediate position”, neither believer nor unbeliever." },
  { id: "jafar", name: "Ja’far al-Sadiq", short: "Ja’far al-Sadiq", ar: "جعفر الصادق", b: 702, bc: true, d: 765, dah: 148, lane: "law", schools: ["Ja’fari"], places: ["medina"],
    text: "Great-grandson of Ali and the sixth Imam of Twelver and Isma’ili Shi’is. He taught law and hadith in Medina. Twelver jurisprudence is named after him, and Sunni scholars, among them Abu Hanifa and Malik, are reported to have learned from him." },
  { id: "ibn-ishaq", name: "Muhammad ibn Ishaq", short: "Ibn Ishaq", ar: "محمد بن إسحاق", b: 704, bc: true, d: 767, dah: 150, lane: "letters", places: ["medina", "baghdad"],
    text: "Medinan historian whose biography of the Prophet is the earliest to survive, mainly in the edition of Ibn Hisham (d. 833).",
    works: [["Sirat rasul Allah", "The life of the Messenger of God"]] },

  // 750–945
  { id: "malik", name: "Malik ibn Anas", short: "Malik", ar: "مالك بن أنس", b: 711, d: 795, dah: 179, lane: "law", also: ["hadith"], schools: ["Maliki"], places: ["medina"], teachers: ["jafar"],
    text: "Jurist and hadith scholar of Medina. His Muwatta’ joins hadith to the practice of the people of Medina. The Maliki school formed around it and came to prevail in North and West Africa and al-Andalus.",
    works: [["al-Muwatta’", "The well-trodden path"]] },
  { id: "rabia", name: "Rabi’a al-Adawiyya", short: "Rabi’a", ar: "رابعة العدوية", b: 717, bc: true, d: 801, dah: 185, lane: "sufism", places: ["basra"],
    text: "Ascetic of Basra remembered for teaching that God should be loved for Himself, not out of fear of hell or hope of paradise. Her sayings survive in later Sufi collections." },
  { id: "sibawayh", name: "Sibawayh", short: "Sibawayh", ar: "سيبويه", b: 760, bc: true, d: 796, dc: true, dah: 180, lane: "letters", places: ["shiraz", "basra"],
    text: "Persian-born grammarian of Basra. His book, known simply as “the Book”, is the first full description of Arabic grammar and the base of the whole grammatical tradition.",
    works: [["al-Kitab", "The Book"]] },
  { id: "shafii", name: "Muhammad ibn Idris al-Shafi’i", short: "al-Shafi’i", ar: "محمد بن إدريس الشافعي", b: 767, d: 820, dah: 204, lane: "law", schools: ["Shafi’i"], places: ["gaza", "mecca", "medina", "baghdad", "cairo"], teachers: ["malik"],
    text: "Jurist who studied with Malik and with the Hanafis of Iraq. In the Risala he ranked the sources of law: the Qur’an, the Prophet’s practice as known through hadith, consensus and analogy. He is regarded as the founder of legal theory and of the Shafi’i school.",
    works: [["al-Risala", "The epistle"], ["Kitab al-Umm", "The mother book"]] },
  { id: "jahiz", name: "al-Jahiz", short: "al-Jahiz", ar: "الجاحظ", b: 776, bc: true, d: 868, dah: 255, lane: "letters", also: ["theology"], schools: ["Mu’tazili"], places: ["basra", "baghdad"],
    text: "Prose writer and Mu’tazili theologian of Basra. His Book of Animals and his essays on rhetoric, society and theology set the standard for Arabic literary prose.",
    works: [["Kitab al-hayawan", "The book of animals"], ["al-Bayan wa’l-tabyin", "Eloquence and clear expression"]] },
  { id: "ibn-hanbal", name: "Ahmad ibn Hanbal", short: "Ibn Hanbal", ar: "أحمد بن حنبل", b: 780, d: 855, dah: 241, lane: "hadith", also: ["law", "theology"], schools: ["Hanbali", "Athari"], places: ["baghdad"], teachers: ["shafii"],
    text: "Hadith scholar and jurist of Baghdad. He refused to affirm that the Qur’an is created during the Mihna and was imprisoned and flogged, which made him a symbol of steadfastness. His Musnad holds about 27,000 reports, and the Hanbali school is named after him.",
    works: [["al-Musnad", "The supported (collection)"]] },
  { id: "khwarizmi", name: "Muhammad ibn Musa al-Khwarizmi", short: "al-Khwarizmi", ar: "محمد بن موسى الخوارزمي", b: 780, bc: true, d: 850, dc: true, lane: "sciences", places: ["urgench", "baghdad"],
    text: "Mathematician and astronomer at the House of Wisdom in Baghdad. His book on “completion and balancing” gave algebra its name, and Latin forms of his name gave us the word algorithm.",
    works: [["al-Kitab al-mukhtasar fi hisab al-jabr wa’l-muqabala", "The compendious book on calculation by completion and balancing"]] },
  { id: "kindi", name: "Ya’qub ibn Ishaq al-Kindi", short: "al-Kindi", ar: "يعقوب بن إسحاق الكندي", b: 801, bc: true, d: 873, dc: true, lane: "philosophy", places: ["kufa", "basra", "baghdad"],
    text: "First major philosopher to write in Arabic, called “the philosopher of the Arabs”. He oversaw translations of Greek works and argued that philosophy and revelation lead to the same truths.",
    works: [["Fi’l-falsafa al-ula", "On first philosophy"]] },
  { id: "bukhari", name: "Muhammad ibn Isma’il al-Bukhari", short: "al-Bukhari", ar: "محمد بن إسماعيل البخاري", b: 810, d: 870, dah: 256, lane: "hadith", places: ["bukhara", "mecca", "baghdad", "nishapur", "samarkand"],
    text: "Born in Bukhara, he travelled for sixteen years collecting hadith. His Sahih, selected by strict criteria for unbroken chains of reliable narrators, is regarded by Sunni Muslims as the most authentic book after the Qur’an. He died in a village near Samarkand.",
    works: [["al-Jami’ al-sahih", "The sound collection"]] },
  { id: "muslim", name: "Muslim ibn al-Hajjaj", short: "Muslim", ar: "مسلم بن الحجاج", b: 817, bc: true, d: 875, dah: 261, lane: "hadith", places: ["nishapur"], teachers: ["bukhari", "ibn-hanbal"],
    text: "Hadith scholar of Nishapur who studied with al-Bukhari and Ibn Hanbal. His Sahih ranks second only to al-Bukhari’s and is valued for gathering every chain of a report in one place.",
    works: [["al-Sahih", "The sound (collection)"]] },
  { id: "abu-dawud", name: "Abu Dawud al-Sijistani", short: "Abu Dawud", ar: "أبو داود السجستاني", b: 817, d: 889, dah: 275, lane: "hadith", places: ["zaranj", "baghdad", "basra"], teachers: ["ibn-hanbal"],
    text: "Hadith scholar from Sijistan who studied with Ibn Hanbal and settled in Basra. His Sunan gathers the reports used in law, with notes on their reliability, and is one of the six canonical Sunni collections.",
    works: [["al-Sunan", "The practices"]] },
  { id: "tirmidhi", name: "Muhammad ibn Isa al-Tirmidhi", short: "al-Tirmidhi", ar: "محمد بن عيسى الترمذي", b: 824, d: 892, dah: 279, lane: "hadith", places: ["termez"], teachers: ["bukhari"],
    text: "Hadith scholar from Termez on the Oxus and a student of al-Bukhari. His Jami’ grades each report and records how the legal schools used it, making it a guide to both hadith and law.",
    works: [["al-Jami’", "The compendium"]] },
  { id: "junayd", name: "al-Junayd al-Baghdadi", short: "al-Junayd", ar: "الجنيد البغدادي", b: 830, bc: true, d: 910, dah: 298, lane: "sufism", places: ["baghdad"],
    text: "Sufi master of Baghdad who taught a “sober” path in which mystical experience stays within the bounds of the Law. Most later Sufi orders trace their chains of masters through him." },
  { id: "tabari", name: "Muhammad ibn Jarir al-Tabari", short: "al-Tabari", ar: "محمد بن جرير الطبري", b: 839, d: 923, dah: 310, lane: "quran", also: ["letters", "law"], places: ["amol", "rayy", "baghdad"],
    text: "Scholar from Amol in Tabaristan who settled in Baghdad. His Qur’an commentary gathers and weighs the reports of early authorities verse by verse, and his History of Prophets and Kings runs from creation to his own time.",
    works: [["Jami’ al-bayan", "The comprehensive clarification (commentary)"], ["Tarikh al-rusul wa’l-muluk", "History of prophets and kings"]] },
  { id: "tahawi", name: "Abu Ja’far al-Tahawi", short: "al-Tahawi", ar: "أبو جعفر الطحاوي", b: 853, d: 933, dah: 321, lane: "theology", also: ["law"], schools: ["Hanafi"], places: ["cairo"],
    text: "Egyptian jurist who moved from the Shafi’i to the Hanafi school. His short creed is accepted across the Sunni theological schools and is still widely taught.",
    works: [["al-Aqida al-Tahawiyya", "The Tahawi creed"]] },
  { id: "maturidi", name: "Abu Mansur al-Maturidi", short: "al-Maturidi", ar: "أبو منصور الماتريدي", b: 853, bc: true, d: 944, dah: 333, lane: "theology", schools: ["Maturidi", "Hanafi"], places: ["samarkand"],
    text: "Hanafi theologian of Samarkand. He defended the creed with reasoned argument and held that reason can know God’s existence and basic good and evil. The Maturidi school became dominant among Hanafis in Central Asia and the Ottoman lands.",
    works: [["Kitab al-tawhid", "The book of divine unity"], ["Ta’wilat al-Qur’an", "Interpretations of the Qur’an"]] },
  { id: "hallaj", name: "al-Husayn ibn Mansur al-Hallaj", short: "al-Hallaj", ar: "الحسين بن منصور الحلاج", b: 858, bc: true, d: 922, dah: 309, lane: "sufism", places: ["shiraz", "basra", "mecca", "baghdad"], teachers: ["junayd"],
    text: "Sufi who preached in public and travelled as far as India. His ecstatic saying “I am the Truth” and political suspicion against him led to a long trial and his execution in Baghdad. He became a lasting symbol for later mystics and poets." },
  { id: "kulayni", name: "Muhammad ibn Ya’qub al-Kulayni", short: "al-Kulayni", ar: "محمد بن يعقوب الكليني", b: 864, bc: true, d: 941, dah: 329, lane: "hadith", schools: ["Ja’fari"], places: ["rayy", "baghdad"],
    text: "Twelver Shi’i scholar from near Rayy who compiled al-Kafi, about 16,000 reports from the Prophet and the Imams on belief and law. It is the first and most important of the Four Books of Twelver hadith.",
    works: [["al-Kafi", "The sufficient"]] },
  { id: "abu-bakr-razi", name: "Abu Bakr al-Razi", short: "Abu Bakr al-Razi", ar: "أبو بكر الرازي", b: 865, bc: true, d: 925, dc: true, lane: "sciences", also: ["philosophy"], places: ["rayy", "baghdad"],
    text: "Physician and philosopher who directed hospitals in Rayy and Baghdad. His treatise on smallpox and measles is the first clear clinical account of each, and his vast medical notebook, al-Hawi, was translated into Latin.",
    works: [["al-Hawi", "The comprehensive book (of medicine)"], ["Fi’l-jadari wa’l-hasba", "On smallpox and measles"]] },
  { id: "farabi", name: "Abu Nasr al-Farabi", short: "al-Farabi", ar: "أبو نصر الفارابي", b: 872, bc: true, d: 950, dah: 339, lane: "philosophy", places: ["otrar", "baghdad", "aleppo", "damascus"],
    text: "Philosopher from Farab on the Syr Darya, called “the Second Teacher” after Aristotle. He wrote on logic, music and the ideal state, and his account of the virtuous city shaped later political philosophy.",
    works: [["Ara’ ahl al-madina al-fadila", "The views of the people of the virtuous city"]] },
  { id: "ashari", name: "Abu al-Hasan al-Ash’ari", short: "al-Ash’ari", ar: "أبو الحسن الأشعري", b: 874, bc: true, d: 936, dah: 324, lane: "theology", schools: ["Ash’ari"], places: ["basra", "baghdad"],
    text: "Trained as a Mu’tazili in Basra, he broke with them around the age of forty. He defended doctrines such as the uncreated Qur’an and the divine attributes with rational argument, and the Ash’ari school became the leading Sunni theology.",
    works: [["Maqalat al-Islamiyyin", "The doctrines of the Muslims"], ["al-Ibana", "The elucidation"]] },
  { id: "masudi", name: "Ali ibn al-Husayn al-Mas’udi", short: "al-Mas’udi", ar: "علي بن الحسين المسعودي", b: 896, bc: true, d: 956, dah: 345, lane: "letters", places: ["baghdad", "cairo"],
    text: "Historian and traveller from Baghdad who visited Iran, India, East Africa and Syria. His Meadows of Gold joins world history to geography and to what he saw on his journeys.",
    works: [["Muruj al-dhahab", "The meadows of gold"]] },

  // 945–1258
  { id: "abd-al-jabbar", name: "Qadi Abd al-Jabbar", short: "Abd al-Jabbar", ar: "القاضي عبد الجبار", b: 935, bc: true, d: 1025, dah: 415, lane: "theology", schools: ["Mu’tazili", "Shafi’i"], places: ["asadabad", "baghdad", "rayy"],
    text: "Chief judge of Rayy under the Buyids and the last great systematiser of Mu’tazili theology. His encyclopaedic al-Mughni sets out the school’s doctrines of God’s unity and justice.",
    works: [["al-Mughni fi abwab al-tawhid wa’l-adl", "The sufficient, on divine unity and justice"]] },
  { id: "mufid", name: "al-Shaykh al-Mufid", short: "al-Mufid", ar: "الشيخ المفيد", b: 948, bc: true, d: 1022, dah: 413, lane: "theology", schools: ["Twelver"], places: ["baghdad"],
    text: "Leading Twelver Shi’i scholar of Baghdad. He used rational theology, close to the Mu’tazila in places, to defend Imami doctrine, and trained the next generation of Twelver jurists.",
    works: [["al-Irshad", "The guidance"], ["Awa’il al-maqalat", "First principles of the doctrines"]] },
  { id: "ibn-haytham", name: "Ibn al-Haytham", short: "Ibn al-Haytham", ar: "ابن الهيثم", b: 965, bc: true, d: 1040, dc: true, lane: "sciences", places: ["basra", "cairo"],
    text: "Mathematician and physicist from Basra who worked in Cairo. His Book of Optics explained vision as light entering the eye and tested claims by controlled experiment. In his Doubts on Ptolemy he exposed contradictions in the accepted model of the heavens.",
    works: [["Kitab al-manazir", "The book of optics"], ["al-Shukuk ala Batlamyus", "Doubts on Ptolemy"]] },
  { id: "mawardi", name: "Abu al-Hasan al-Mawardi", short: "al-Mawardi", ar: "أبو الحسن الماوردي", b: 972, d: 1058, dah: 450, lane: "law", schools: ["Shafi’i"], places: ["basra", "baghdad"],
    text: "Shafi’i judge in Baghdad and envoy of the Abbasid caliphs. His Ordinances of Government gave the classic juristic account of the caliphate and its delegated powers, at a time when real power lay with the Buyids and then the Seljuqs.",
    works: [["al-Ahkam al-sultaniyya", "The ordinances of government"]] },
  { id: "biruni", name: "Abu al-Rayhan al-Biruni", short: "al-Biruni", ar: "أبو الريحان البيروني", b: 973, d: 1048, dc: true, lane: "sciences", places: ["kath", "urgench", "ghazna"],
    text: "Scholar from Kath in Khwarazm who served the courts of Khwarazm and Ghazna. He measured the radius of the Earth and wrote on astronomy, minerals and calendars. His book on India describes its religion and science with rare care.",
    works: [["Tahqiq ma li’l-Hind", "An inquiry into India"], ["al-Qanun al-Mas’udi", "The Mas’udic canon"]] },
  { id: "karima", name: "Karima al-Marwaziyya", short: "Karima al-Marwaziyya", ar: "كريمة المروزية", b: 974, bc: true, d: 1070, dah: 463, lane: "hadith", places: ["merv", "mecca"],
    text: "Hadith scholar born near Merv who settled in Mecca. She was a leading authority on the text of al-Bukhari’s Sahih, and her copy became one of its most trusted transmissions. Al-Khatib al-Baghdadi read the whole Sahih with her in five days." },
  { id: "ibn-sina", name: "Ibn Sina (Avicenna)", short: "Ibn Sina", ar: "ابن سينا", b: 980, bc: true, d: 1037, dah: 428, lane: "philosophy", also: ["sciences"], places: ["bukhara", "urgench", "rayy", "hamadan", "isfahan"],
    text: "Philosopher and physician born near Bukhara. His Book of Healing built a complete philosophical system, and his Canon of Medicine was a standard text in the Islamic world and Europe for centuries. His distinction between essence and existence shaped later theology.",
    works: [["Kitab al-shifa’", "The book of healing"], ["al-Qanun fi’l-tibb", "The canon of medicine"]] },
  { id: "qushayri", name: "Abd al-Karim al-Qushayri", short: "al-Qushayri", ar: "عبد الكريم القشيري", b: 986, d: 1072, dah: 465, lane: "sufism", schools: ["Shafi’i", "Ash’ari"], places: ["nishapur"],
    text: "Sufi and Ash’ari scholar of Nishapur. His Epistle gathers the lives and sayings of early Sufis and defines Sufi terms, presenting the path as consistent with Sunni law and creed. It remains the standard handbook of Sufism.",
    works: [["al-Risala al-Qushayriyya", "The Qushayri epistle"]] },
  { id: "ibn-hazm", name: "Ibn Hazm", short: "Ibn Hazm", ar: "ابن حزم", b: 994, d: 1064, dah: 456, lane: "law", also: ["letters"], schools: ["Zahiri"], places: ["cordoba"],
    text: "Andalusian scholar, poet and court official of Cordoba. He defended the Zahiri method, which holds to the plain sense of the texts and rejects analogy, and wrote an early comparative study of religions. His Ring of the Dove is a classic treatise on love.",
    works: [["al-Muhalla", "The adorned"], ["al-Fisal fi’l-milal", "Distinctions among the religions"], ["Tawq al-hamama", "The ring of the dove"]] },
  { id: "shaykh-tusi", name: "al-Shaykh al-Tusi", short: "al-Shaykh al-Tusi", ar: "الشيخ الطوسي", b: 995, d: 1067, dah: 460, lane: "law", also: ["hadith"], schools: ["Ja’fari"], places: ["tus", "baghdad", "najaf"], teachers: ["mufid"],
    text: "Twelver scholar from Tus who studied with al-Mufid in Baghdad. He wrote two of the Four Books of Shi’i hadith and major works on law and its theory. After his house was burned in 1056 he moved to Najaf, which became a centre of Shi’i learning.",
    works: [["Tahdhib al-ahkam", "The refinement of rulings"], ["al-Istibsar", "The examination"]] },
  { id: "kashgari", name: "Mahmud al-Kashgari", short: "al-Kashgari", ar: "محمود الكاشغري", b: 1005, bc: true, d: 1102, dc: true, lane: "letters", places: ["kashgar", "baghdad"],
    text: "Turkic scholar from the Karakhanid lands who settled in Baghdad. His Compendium of the Languages of the Turks, finished in 1072–74, is the first dictionary of the Turkic languages, explained in Arabic, with poems, proverbs and a round map.",
    works: [["Diwan lughat al-Turk", "Compendium of the languages of the Turks"]] },
  { id: "jurjani", name: "Abd al-Qahir al-Jurjani", short: "Abd al-Qahir al-Jurjani", ar: "عبد القاهر الجرجاني", b: 1009, bc: true, d: 1078, dah: 471, lane: "letters", places: ["jurjan"],
    text: "Grammarian of Jurjan who founded the theory of Arabic rhetoric. He argued that eloquence lies in the arrangement of words, and used this to explain the inimitability of the Qur’an.",
    works: [["Dala’il al-i’jaz", "Proofs of inimitability"], ["Asrar al-balagha", "The secrets of eloquence"]] },
  { id: "juwayni", name: "al-Juwayni", short: "al-Juwayni", ar: "إمام الحرمين الجويني", b: 1028, d: 1085, dah: 478, lane: "theology", also: ["law"], schools: ["Ash’ari", "Shafi’i"], places: ["nishapur", "mecca", "medina", "nishapur"],
    text: "Ash’ari theologian and Shafi’i jurist, called “Imam of the Two Sanctuaries” after teaching in Mecca and Medina. He headed the Nizamiyya college in Nishapur, where al-Ghazali was his student.",
    works: [["al-Irshad", "The guide"], ["al-Burhan fi usul al-fiqh", "The proof, on legal theory"]] },
  { id: "omar-khayyam", name: "Omar Khayyam", short: "Omar Khayyam", ar: "عمر الخيام", b: 1048, d: 1131, lane: "sciences", places: ["nishapur", "samarkand", "isfahan", "nishapur"],
    text: "Mathematician and astronomer of Nishapur. He solved cubic equations by intersecting conic sections and led the reform that produced the Jalali calendar for the Seljuq sultan. The Persian quatrains attributed to him made him famous in Europe.",
    works: [["Risala fi’l-barahin ala masa’il al-jabr wa’l-muqabala", "Treatise on the proofs of algebra"]] },
  { id: "ghazali", name: "Abu Hamid al-Ghazali", short: "al-Ghazali", ar: "أبو حامد الغزالي", b: 1058, d: 1111, dah: 505, lane: "theology", also: ["sufism", "law", "philosophy"], schools: ["Ash’ari", "Shafi’i"], places: ["tus", "nishapur", "baghdad", "damascus", "jerusalem", "tus"], teachers: ["juwayni"],
    text: "Ash’ari theologian and Shafi’i jurist who taught at the Nizamiyya in Baghdad. In The Incoherence of the Philosophers he rejected key doctrines of Ibn Sina. After a crisis in 1095 he left his post for a Sufi life, and his Revival of the Religious Sciences joined law, theology and spirituality.",
    works: [["Tahafut al-falasifa", "The incoherence of the philosophers"], ["Ihya’ ulum al-din", "The revival of the religious sciences"], ["al-Munqidh min al-dalal", "The deliverer from error"]] },
  { id: "abu-hafs-nasafi", name: "Najm al-Din Abu Hafs al-Nasafi", short: "Abu Hafs al-Nasafi", ar: "نجم الدين عمر النسفي", b: 1067, d: 1142, dah: 537, lane: "theology", schools: ["Maturidi", "Hanafi"], places: ["nasaf", "bukhara", "samarkand"],
    text: "Hanafi jurist and Maturidi theologian of Samarkand. His short creed was taught for centuries, above all through al-Taftazani’s commentary.",
    works: [["al-Aqa’id", "The creed"]] },
  { id: "zamakhshari", name: "al-Zamakhshari", short: "al-Zamakhshari", ar: "الزمخشري", b: 1075, d: 1144, dah: 538, lane: "quran", also: ["letters"], schools: ["Mu’tazili", "Hanafi"], places: ["zamakhshar", "bukhara", "mecca", "urgench"],
    text: "Philologist and Mu’tazili theologian from Khwarazm who lived for years in Mecca. His commentary al-Kashshaf explains the Qur’an’s grammar and rhetoric with great precision; Sunni scholars valued it while correcting its Mu’tazili readings.",
    works: [["al-Kashshaf", "The unveiler"]] },
  { id: "jilani", name: "Abd al-Qadir al-Jilani", short: "Abd al-Qadir al-Jilani", ar: "عبد القادر الجيلاني", b: 1078, d: 1166, dah: 561, lane: "sufism", schools: ["Hanbali", "Qadiri"], places: ["gilan", "baghdad"],
    text: "Hanbali preacher and teacher from Gilan who ran a school and hospice in Baghdad. His sermons urged obedience to the Law and sincerity before God. The Qadiri order, among the most widespread Sufi orders, traces itself to him.",
    works: [["Futuh al-ghayb", "Revelations of the unseen"], ["al-Ghunya", "Sufficient provision"]] },
  { id: "yasawi", name: "Ahmad Yasawi", short: "Ahmad Yasawi", ar: "أحمد يسوي", b: 1093, bc: true, d: 1166, lane: "sufism", places: ["sayram", "bukhara", "turkistan"],
    text: "Sufi master from Sayram who studied in Bukhara and taught in the town of Yasi, now Turkistan. Verses in Turkic attributed to him spread Sufi teaching among the Turkic peoples of the steppe. Timur later built the great shrine over his grave.",
    works: [["Divan-i hikmat", "Book of wisdom (attributed)"]] },
  { id: "ibn-tufayl", name: "Ibn Tufayl", short: "Ibn Tufayl", ar: "ابن طفيل", b: 1105, bc: true, d: 1185, dah: 581, lane: "philosophy", places: ["guadix", "granada", "marrakesh"],
    text: "Andalusian physician and philosopher at the Almohad court in Marrakesh. His tale Hayy ibn Yaqzan tells of a child raised alone on an island who reaches knowledge of God by reason and contemplation. He introduced Ibn Rushd to the caliph.",
    works: [["Hayy ibn Yaqzan", "Alive, son of Awake"]] },
  { id: "marghinani", name: "Burhan al-Din al-Marghinani", short: "al-Marghinani", ar: "برهان الدين المرغيناني", b: 1117, bc: true, d: 1197, dah: 593, lane: "law", schools: ["Hanafi", "Maturidi"], places: ["marghinan", "samarkand"], teachers: ["abu-hafs-nasafi"],
    text: "Hanafi jurist from Marghinan in the Fergana Valley who died in Samarkand. His al-Hidaya became the standard Hanafi textbook of law, taught in madrasas from Central Asia to India and the Ottoman lands.",
    works: [["al-Hidaya", "The guidance"]] },
  { id: "ibn-rushd", name: "Ibn Rushd (Averroes)", short: "Ibn Rushd", ar: "ابن رشد", b: 1126, d: 1198, dah: 595, lane: "philosophy", also: ["law"], schools: ["Maliki"], places: ["cordoba", "seville", "marrakesh"],
    text: "Maliki judge and philosopher of Cordoba, known in Europe as Averroes. He commented on nearly all of Aristotle and answered al-Ghazali in The Incoherence of the Incoherence, arguing that the Law itself commands philosophical study.",
    works: [["Tahafut al-tahafut", "The incoherence of the incoherence"], ["Fasl al-maqal", "The decisive treatise"], ["Bidayat al-mujtahid", "The beginning for the independent jurist"]] },
  { id: "kubra", name: "Najm al-Din Kubra", short: "Najm al-Din Kubra", ar: "نجم الدين كبرى", b: 1145, d: 1221, dah: 618, lane: "sufism", places: ["urgench"],
    text: "Sufi master of Khwarazm who described the visions and coloured lights seen on the mystical path. He founded the Kubrawi order and was killed when the Mongols took Gurganj in 1221." },
  { id: "fakhr-razi", name: "Fakhr al-Din al-Razi", short: "Fakhr al-Din al-Razi", ar: "فخر الدين الرازي", b: 1150, d: 1210, dah: 606, lane: "theology", also: ["quran", "philosophy"], schools: ["Ash’ari", "Shafi’i"], places: ["rayy", "bukhara", "samarkand", "herat"],
    text: "Ash’ari theologian from Rayy who brought the methods and questions of Ibn Sina into theology. His long Qur’an commentary treats theology, philosophy and natural science alongside exegesis. He debated scholars across Khurasan and Transoxiana and died in Herat.",
    works: [["Mafatih al-ghayb", "The keys to the unseen"], ["al-Matalib al-aliya", "The highest aims"]] },
  { id: "suhrawardi", name: "Shihab al-Din Suhrawardi", short: "Suhrawardi", ar: "شهاب الدين السهروردي", b: 1154, d: 1191, dah: 587, lane: "philosophy", places: ["suhraward", "isfahan", "aleppo"],
    text: "Philosopher who founded the school of Illumination, which describes reality as degrees of light and draws on ancient Persian wisdom. He was executed in Aleppo, and his ideas shaped later philosophy in Iran.",
    works: [["Hikmat al-ishraq", "The philosophy of illumination"]] },
  { id: "ibn-arabi", name: "Muhyi al-Din Ibn Arabi", short: "Ibn Arabi", ar: "محيي الدين ابن عربي", b: 1165, d: 1240, dah: 638, lane: "sufism", places: ["murcia", "seville", "mecca", "konya", "damascus"],
    text: "Andalusian Sufi born in Murcia who travelled east and settled in Damascus. In The Meccan Revelations and The Bezels of Wisdom he described all things as manifestations of God. His followers summed up the teaching as the unity of being.",
    works: [["al-Futuhat al-Makkiyya", "The Meccan revelations"], ["Fusus al-hikam", "The bezels of wisdom"]] },

  // 1258–1500
  { id: "nasir-tusi", name: "Nasir al-Din al-Tusi", short: "Nasir al-Din al-Tusi", ar: "نصير الدين الطوسي", b: 1201, d: 1274, dah: 672, lane: "sciences", also: ["theology", "philosophy"], schools: ["Twelver"], places: ["tus", "nishapur", "alamut", "maragha", "baghdad"],
    text: "Astronomer, philosopher and Twelver theologian from Tus. After serving the Isma’ili rulers of Alamut he joined the Mongol Hulagu, who built him the Maragha observatory. His planetary models challenged Ptolemy, and his creed became a basis of Shi’i theology.",
    works: [["al-Tadhkira fi ilm al-hay’a", "Memoir on astronomy"], ["Tajrid al-i’tiqad", "The abstract of belief"]] },
  { id: "rumi", name: "Jalal al-Din Rumi", short: "Rumi", ar: "جلال الدين الرومي", b: 1207, d: 1273, dah: 672, lane: "sufism", places: ["balkh", "konya"],
    text: "Persian poet and scholar born in the region of Balkh whose family fled the Mongols and settled in Konya. His meeting with the wanderer Shams of Tabriz turned him to mystical poetry. His Masnavi is among the most read works of Sufism, and the Mevlevi order formed around his tomb.",
    works: [["Masnavi-yi ma’navi", "The spiritual couplets"], ["Divan-i Shams", "The poems of Shams"]] },
  { id: "ibn-nafis", name: "Ibn al-Nafis", short: "Ibn al-Nafis", ar: "ابن النفيس", b: 1213, bc: true, d: 1288, dah: 687, lane: "sciences", schools: ["Shafi’i"], places: ["damascus", "cairo"],
    text: "Physician from Damascus who headed the Mansuri hospital in Cairo. In a commentary on Ibn Sina’s Canon he described the pulmonary circulation, blood passing from the heart to the lungs and back, three centuries before European physicians.",
    works: [["Sharh tashrih al-Qanun", "Commentary on the anatomy of the Canon"]] },
  { id: "nawawi", name: "Yahya ibn Sharaf al-Nawawi", short: "al-Nawawi", ar: "يحيى بن شرف النووي", b: 1233, d: 1277, dah: 676, lane: "hadith", also: ["law"], schools: ["Shafi’i"], places: ["nawa", "damascus"],
    text: "Shafi’i jurist and hadith scholar of Damascus. His Forty Hadith and Gardens of the Righteous are among the most read books in the Muslim world, and his legal works define the Shafi’i school’s settled positions.",
    works: [["al-Arba’un", "The forty (hadith)"], ["Riyad al-salihin", "Gardens of the righteous"], ["Minhaj al-talibin", "The students’ path"]] },
  { id: "hilli", name: "al-Allama al-Hilli", short: "al-Allama al-Hilli", ar: "العلامة الحلي", b: 1250, d: 1325, dah: 726, lane: "law", also: ["theology"], schools: ["Ja’fari"], places: ["hilla", "maragha", "sultaniyya", "hilla"], teachers: ["nasir-tusi"],
    text: "Twelver jurist and theologian of Hilla and a student of Nasir al-Din al-Tusi. He gave ijtihad, reasoned legal judgment, a formal place in Twelver law. He is said to have brought the Ilkhan Öljeitü to Shi’ism.",
    works: [["Kashf al-murad", "Unveiling the intended (commentary on al-Tusi)"], ["Tahrir al-ahkam", "The redaction of rulings"]] },
  { id: "ibn-taymiyya", name: "Ibn Taymiyya", short: "Ibn Taymiyya", ar: "ابن تيمية", b: 1263, d: 1328, dah: 728, lane: "theology", also: ["law"], schools: ["Hanbali", "Athari"], places: ["harran", "damascus", "cairo", "damascus"],
    text: "Hanbali scholar of Damascus. He argued for following scripture and the early Muslims directly, criticised philosophers, speculative theologians and some Sufi practices, and claimed the right to independent judgment. Several of his rulings led to imprisonment, and he died in the citadel of Damascus.",
    works: [["Dar’ ta’arud al-aql wa’l-naql", "Averting conflict between reason and revelation"], ["al-Aqida al-Wasitiyya", "The creed for the people of Wasit"]] },
  { id: "ibn-qayyim", name: "Ibn Qayyim al-Jawziyya", short: "Ibn Qayyim", ar: "ابن قيم الجوزية", b: 1292, d: 1350, dah: 751, lane: "law", schools: ["Hanbali"], places: ["damascus"], teachers: ["ibn-taymiyya"],
    text: "Hanbali scholar of Damascus and Ibn Taymiyya’s leading student. He wrote on legal method, the Prophet’s practice and the spiritual life, and argued that the Law serves justice and human welfare throughout.",
    works: [["I’lam al-muwaqqi’in", "Informing those who sign (fatwas)"], ["Zad al-ma’ad", "Provision for the hereafter"], ["Madarij al-salikin", "Stations of the seekers"]] },
  { id: "ibn-kathir", name: "Isma’il ibn Kathir", short: "Ibn Kathir", ar: "إسماعيل بن كثير", b: 1300, bc: true, d: 1373, dah: 774, lane: "quran", also: ["letters"], schools: ["Shafi’i"], places: ["bosra", "damascus"], teachers: ["ibn-taymiyya"],
    text: "Shafi’i scholar of Damascus and a student of Ibn Taymiyya. His Qur’an commentary explains verses first by other verses and by hadith, and became one of the most widely read. His history runs from creation to his own day.",
    works: [["Tafsir al-Qur’an al-azim", "Commentary on the mighty Qur’an"], ["al-Bidaya wa’l-nihaya", "The beginning and the end"]] },
  { id: "naqshband", name: "Baha’ al-Din Naqshband", short: "Baha’ al-Din Naqshband", ar: "بهاء الدين نقشبند", b: 1318, d: 1389, dah: 791, lane: "sufism", places: ["bukhara"],
    text: "Sufi master of Qasr-i Arifan near Bukhara. He taught silent remembrance of God and “solitude in the crowd”, staying engaged in daily life. The Naqshbandi order spread from Bukhara across Central Asia, India and the Ottoman lands." },
  { id: "shatibi", name: "Abu Ishaq al-Shatibi", short: "al-Shatibi", ar: "أبو إسحاق الشاطبي", b: 1320, bc: true, d: 1388, dah: 790, lane: "law", schools: ["Maliki"], places: ["granada"],
    text: "Maliki jurist of Granada. In The Concordances he rebuilt legal theory around the purposes of the Law: protecting religion, life, intellect, lineage and property. Long neglected, his work was revived by modern reformers.",
    works: [["al-Muwafaqat", "The concordances"], ["al-I’tisam", "Holding fast"]] },
  { id: "taftazani", name: "Sa’d al-Din al-Taftazani", short: "al-Taftazani", ar: "سعد الدين التفتازاني", b: 1322, d: 1390, dah: 792, lane: "theology", places: ["nasa", "herat", "samarkand"],
    text: "Scholar from Khurasan who taught at Timur’s court in Samarkand. His commentaries on logic, rhetoric, legal theory and al-Nasafi’s creed became core textbooks in madrasas from the Ottoman lands to India.",
    works: [["Sharh al-Aqa’id al-Nasafiyya", "Commentary on al-Nasafi’s creed"], ["al-Mutawwal", "The long (commentary on rhetoric)"]] },
  { id: "ibn-khaldun", name: "Ibn Khaldun", short: "Ibn Khaldun", ar: "ابن خلدون", b: 1332, d: 1406, dah: 808, lane: "letters", schools: ["Maliki"], places: ["tunis", "fez", "granada", "cairo", "damascus", "cairo"],
    text: "Historian and Maliki judge born in Tunis who served courts across North Africa and al-Andalus and ended his life in Cairo. In the Muqaddima he explained the rise and fall of dynasties through group solidarity. He met Timur outside Damascus in 1401.",
    works: [["al-Muqaddima", "The introduction"], ["Kitab al-ibar", "The book of lessons"]] },
  { id: "ibn-hajar", name: "Ibn Hajar al-Asqalani", short: "Ibn Hajar", ar: "ابن حجر العسقلاني", b: 1372, d: 1449, dah: 852, lane: "hadith", schools: ["Shafi’i"], places: ["cairo"],
    text: "Shafi’i hadith scholar and chief judge of Cairo. His commentary on al-Bukhari, Fath al-Bari, took about twenty-five years and is the standard reference on the Sahih. He also wrote major dictionaries of narrators.",
    works: [["Fath al-Bari", "The victory of the Creator"], ["Tahdhib al-tahdhib", "The refinement of the refinement"]] },
  { id: "ulugh-beg", name: "Ulugh Beg", short: "Ulugh Beg", ar: "ألغ بيك", b: 1394, d: 1449, dah: 853, lane: "sciences", places: ["samarkand"],
    text: "Timurid ruler of Samarkand and astronomer. He founded a madrasa and an observatory whose great meridian instrument measured stellar positions with new precision. His star tables were used for centuries. He was killed in a revolt led by his son.",
    works: [["Zij-i Sultani", "The sultan’s astronomical tables"]] },
  { id: "qushji", name: "Ali Qushji", short: "Ali Qushji", ar: "علي القوشجي", b: 1403, d: 1474, dah: 879, lane: "sciences", places: ["samarkand", "herat", "tabriz", "istanbul"], teachers: ["ulugh-beg"],
    text: "Astronomer of Samarkand who completed Ulugh Beg’s star tables. He argued that astronomy need not rest on Aristotle’s physics and held that the Earth’s rotation could not be ruled out. He later taught in Istanbul under Mehmed II.",
    works: [["Sharh-i Zij-i Sultani", "Commentary on the sultan’s tables"]] },
  { id: "jami", name: "Abd al-Rahman Jami", short: "Jami", ar: "عبد الرحمن جامي", b: 1414, d: 1492, dah: 898, lane: "sufism", also: ["letters"], schools: ["Naqshbandi"], places: ["jam", "herat", "samarkand", "herat"],
    text: "Persian poet and Naqshbandi Sufi of Herat. His Seven Thrones and his works explaining Ibn Arabi’s thought made him the leading scholar-poet of Timurid Herat.",
    works: [["Haft awrang", "The seven thrones"], ["Nafahat al-uns", "Breaths of intimacy"], ["Lawa’ih", "Flashes of light"]] },
  { id: "navoi", name: "Alisher Navoi", short: "Alisher Navoi", ar: "علي شير نوائي", b: 1441, d: 1501, dah: 906, lane: "letters", places: ["herat", "samarkand", "mashhad", "herat"], teachers: ["jami"],
    text: "Poet and statesman of Timurid Herat and patron of scholars and artists. He wrote mainly in Chagatai Turkic, and in The Judgment of Two Languages argued that Turkic could match Persian as a literary language. He is honoured as the founder of Uzbek literature.",
    works: [["Khamsa", "The quintet"], ["Muhakamat al-lughatayn", "The judgment of two languages"]] },
  { id: "suyuti", name: "Jalal al-Din al-Suyuti", short: "al-Suyuti", ar: "جلال الدين السيوطي", b: 1445, d: 1505, dah: 911, lane: "quran", also: ["hadith", "law"], schools: ["Shafi’i"], places: ["cairo"],
    text: "Shafi’i scholar of Cairo who wrote several hundred works on the Qur’an, hadith, law, grammar and history. His al-Itqan is a standard handbook of the Qur’anic sciences, and he completed the Tafsir al-Jalalayn begun by his teacher al-Mahalli.",
    works: [["al-Itqan fi ulum al-Qur’an", "Mastery of the Qur’anic sciences"], ["Tafsir al-Jalalayn", "Commentary of the two Jalals"]] },
  { id: "aisha-bauniyya", name: "Aisha al-Ba’uniyya", short: "Aisha al-Ba’uniyya", ar: "عائشة الباعونية", b: 1456, bc: true, d: 1517, dah: 922, lane: "sufism", also: ["letters"], places: ["damascus", "cairo", "damascus"],
    text: "Sufi master and poet of Damascus from a family of scholars and judges. She probably wrote more works in Arabic than any other woman before the twentieth century, including poems in praise of the Prophet and a treatise on the Sufi path.",
    works: [["al-Muntakhab fi usul al-rutab", "Selections on the principles of the stations"]] },

  // 1500–1800
  { id: "ebussuud", name: "Ebussuud Efendi", short: "Ebussuud", ar: "أبو السعود أفندي", b: 1490, d: 1574, dah: 982, lane: "law", also: ["quran"], schools: ["Hanafi"], places: ["istanbul"],
    text: "Chief jurist (şeyhülislam) of the Ottoman Empire under Süleyman. His fatwas harmonised sultanic law with Hanafi law on land, taxes and endowments. He also wrote a well-known Qur’an commentary.",
    works: [["Irshad al-aql al-salim", "Guiding the sound mind (commentary)"]] },
  { id: "sirhindi", name: "Ahmad Sirhindi", short: "Ahmad Sirhindi", ar: "أحمد السرهندي", b: 1564, d: 1624, dah: 1034, lane: "sufism", schools: ["Naqshbandi", "Hanafi"], places: ["sirhind", "agra", "delhi", "sirhind"],
    text: "Naqshbandi master of Sirhind in Mughal India, called the “renewer of the second millennium”. His letters criticised the religious policy of Akbar’s court and qualified Ibn Arabi’s unity of being with a “unity of witnessing”.",
    works: [["Maktubat", "Letters"]] },
  { id: "mulla-sadra", name: "Mulla Sadra", short: "Mulla Sadra", ar: "ملا صدرا", b: 1572, bc: true, d: 1640, dc: true, dah: 1050, lane: "philosophy", schools: ["Twelver"], places: ["shiraz", "qazvin", "isfahan", "qom", "shiraz", "basra"],
    text: "Philosopher of Safavid Iran born in Shiraz. His “transcendent philosophy” holds that existence, not essence, is fundamental and that all substance is in motion, drawing together Ibn Sina, Suhrawardi, Ibn Arabi and Shi’i theology. He died around 1640, reportedly at Basra on pilgrimage.",
    works: [["al-Asfar al-arba’a", "The four journeys"]] },
  { id: "katib-celebi", name: "Katib Çelebi", short: "Katib Çelebi", ar: "كاتب جلبي", b: 1609, d: 1657, dah: 1067, lane: "letters", places: ["istanbul", "aleppo", "istanbul"],
    text: "Ottoman scholar and official in Istanbul, also called Hajji Khalifa. His bibliography lists some 15,000 books in Arabic, Persian and Turkish, and his geography drew on European atlases. He urged the use of reason in public disputes.",
    works: [["Kashf al-zunun", "Removal of doubts (bibliography)"], ["Cihannüma", "Mirror of the world"], ["Mizan al-haqq", "The balance of truth"]] },
  { id: "shah-wali-allah", name: "Shah Wali Allah of Delhi", short: "Shah Wali Allah", ar: "شاه ولي الله الدهلوي", b: 1703, d: 1762, dah: 1176, lane: "hadith", also: ["law", "theology"], schools: ["Hanafi", "Naqshbandi"], places: ["delhi", "mecca", "medina", "delhi"],
    text: "Scholar of Delhi who studied hadith in Mecca and Medina. He translated the Qur’an into Persian, urged a return to hadith study and wider use of reasoned judgment, and explained the wisdom behind the Law in The Conclusive Argument from God.",
    works: [["Hujjat Allah al-baligha", "The conclusive argument from God"]] },
  { id: "ibn-abd-al-wahhab", name: "Muhammad ibn Abd al-Wahhab", short: "Ibn Abd al-Wahhab", ar: "محمد بن عبد الوهاب", b: 1703, d: 1792, dah: 1206, lane: "theology", schools: ["Hanbali"], places: ["uyaynah", "medina", "basra", "diriyah"],
    text: "Hanbali scholar of Najd who called for strict monotheism and condemned practices such as seeking the intercession of saints at tombs. His alliance with Muhammad ibn Saud of Diriyah in 1744 joined his movement to the first Saudi state. Many scholars opposed his teaching from the start.",
    works: [["Kitab al-tawhid", "The book of monotheism"]] },
  { id: "dan-fodio", name: "Usman dan Fodio", short: "Usman dan Fodio", ar: "عثمان بن فودي", b: 1754, d: 1817, dah: 1232, lane: "law", schools: ["Maliki", "Qadiri"], places: ["degel", "sokoto"],
    text: "Fulani scholar and preacher of Gobir in Hausaland. His call to reform religious practice and government led to a jihad from 1804 and the founding of the Sokoto Caliphate, the largest West African state of its time. He wrote more than a hundred works in Arabic and Fulfulde.",
    works: [["Ihya’ al-sunna", "Reviving the sunna"], ["Bayan wujub al-hijra", "On the duty of emigration"]] },
  { id: "shawkani", name: "Muhammad ibn Ali al-Shawkani", short: "al-Shawkani", ar: "محمد بن علي الشوكاني", b: 1759, d: 1834, dah: 1250, lane: "law", places: ["sanaa"],
    text: "Yemeni scholar and chief judge of Sana’a, from a Zaydi Shi’i background. He rejected fixed adherence to any one school and argued for judging directly from the Qur’an and hadith.",
    works: [["Nayl al-awtar", "Attaining the goals"], ["Irshad al-fuhul", "Guidance for the masters (legal theory)"]] },

  // 1800 onward
  { id: "nana-asmau", name: "Nana Asma’u", short: "Nana Asma’u", ar: "نانا أسماء", b: 1793, d: 1864, lane: "letters", schools: ["Qadiri"], places: ["degel", "sokoto"],
    text: "Scholar and poet, daughter of Usman dan Fodio. She wrote in Arabic, Fulfulde and Hausa and organised the ’Yan Taru, a network of women teachers that carried education to women across the Sokoto Caliphate." },
  { id: "tahtawi", name: "Rifa’a al-Tahtawi", short: "al-Tahtawi", ar: "رفاعة الطهطاوي", b: 1801, d: 1873, lane: "letters", places: ["tahta", "cairo", "paris", "cairo"],
    text: "Al-Azhar scholar who served as imam to the first Egyptian student mission in Paris (1826–31). His account of France described European institutions for Arabic readers, and he later directed Egypt’s School of Languages.",
    works: [["Takhlis al-ibriz fi talkhis Bariz", "The refinement of gold in summarising Paris"]] },
  { id: "sayyid-ahmad-khan", name: "Sayyid Ahmad Khan", short: "Sayyid Ahmad Khan", ar: "سيد أحمد خان", b: 1817, d: 1898, lane: "letters", also: ["quran"], places: ["delhi", "aligarh"],
    text: "Scholar and official of Delhi. After the uprising of 1857 he urged Indian Muslims to take up modern scientific education and founded the Muhammadan Anglo-Oriental College at Aligarh in 1875. He read the Qur’an as in harmony with the laws of nature." },
  { id: "marjani", name: "Shihab al-Din Marjani", short: "Marjani", ar: "شهاب الدين المرجاني", b: 1818, d: 1889, lane: "theology", also: ["letters"], schools: ["Hanafi"], places: ["kazan", "bukhara", "samarkand", "kazan"],
    text: "Tatar theologian and historian who studied in Bukhara and Samarkand and became imam of Kazan’s First Mosque. He criticised blind imitation in theology and law and wrote histories of the Volga Tatars. He is seen as a forerunner of the Jadids.",
    works: [["Mustafad al-akhbar", "Useful reports (history of Kazan and Bulghar)"]] },
  { id: "afghani", name: "Jamal al-Din al-Afghani", short: "al-Afghani", ar: "جمال الدين الأفغاني", b: 1838, d: 1897, lane: "philosophy", places: ["asadabad", "kabul", "cairo", "paris", "istanbul"],
    text: "Activist and thinker who worked in Afghanistan, India, Egypt, Iran and Istanbul. He called for Muslim unity against European empire and for a revival of reason and philosophy in Islam. His Paris journal, edited with Muhammad Abduh, was read across the Muslim world.",
    works: [["al-Urwa al-wuthqa", "The firmest bond (journal, 1884)"]] },
  { id: "abduh", name: "Muhammad Abduh", short: "Muhammad Abduh", ar: "محمد عبده", b: 1849, d: 1905, lane: "theology", also: ["quran", "law"], places: ["cairo", "beirut", "paris", "cairo"], teachers: ["afghani"],
    text: "Egyptian scholar, student of al-Afghani, and Grand Mufti of Egypt from 1899. He argued that Islam and reason agree, called for reform of al-Azhar and of the courts, and rejected blind imitation. His Theology of Unity and his Qur’an lectures shaped modern reform.",
    works: [["Risalat al-tawhid", "The theology of unity"]] },
  { id: "gasprinski", name: "Ismail Gasprinski", short: "Gasprinski", ar: "إسماعيل غصبرينسكي", b: 1851, d: 1914, lane: "letters", places: ["bakhchysarai"],
    text: "Crimean Tatar educator and publisher. His “new method” schools taught reading by sound along with modern subjects, and his newspaper Terjüman, in a common Turkic language, reached readers from the Balkans to Central Asia. The Jadid movement took its name from his method.",
    works: [["Terjüman", "The interpreter (newspaper, 1883–1918)"]] },
  { id: "rida", name: "Muhammad Rashid Rida", short: "Rashid Rida", ar: "محمد رشيد رضا", b: 1865, d: 1935, lane: "quran", also: ["law"], places: ["qalamun", "cairo"], teachers: ["abduh"],
    text: "Syrian-born scholar who moved to Cairo to work with Muhammad Abduh. His journal al-Manar spread reformist ideas across the Muslim world, and he continued Abduh’s Qur’an commentary. After 1924 he wrote on restoring the caliphate.",
    works: [["al-Manar", "The lighthouse (journal, 1898–1935)"], ["al-Khilafa", "The caliphate"]] },
  { id: "behbudi", name: "Mahmudkhoja Behbudi", short: "Behbudi", ar: "محمودخواجه بهبودی", b: 1875, d: 1919, lane: "letters", places: ["samarkand", "nasaf"],
    text: "Jadid reformer, mufti and publisher of Samarkand. He opened new method schools, wrote textbooks and published the journal Oyina. His play The Patricide (1911) was the first modern drama in Central Asia. He was killed in Qarshi in 1919.",
    works: [["Padarkush", "The patricide (play)"], ["Oyina", "The mirror (journal, 1913–15)"]] },
  { id: "iqbal", name: "Muhammad Iqbal", short: "Iqbal", ar: "محمد إقبال", b: 1877, d: 1938, lane: "philosophy", also: ["letters"], places: ["sialkot", "lahore", "cambridge", "munich", "lahore"],
    text: "Poet and philosopher of Lahore who studied at Cambridge and Munich. In Persian and Urdu poetry and in The Reconstruction of Religious Thought in Islam he called for dynamic thought and renewed ijtihad. His 1930 address proposed a Muslim state in north-west India.",
    works: [["The Reconstruction of Religious Thought in Islam", "Lectures, 1930"], ["Asrar-i khudi", "Secrets of the self"]] },
  { id: "nursi", name: "Bediuzzaman Said Nursi", short: "Said Nursi", ar: "بديع الزمان سعيد النورسي", b: 1877, bc: true, d: 1960, dah: 1379, lane: "theology", schools: ["Shafi’i", "Ash’ari"], places: ["nurs", "van", "istanbul", "kostroma", "istanbul", "barla", "isparta", "urfa"],
    text: "Kurdish scholar from the village of Nurs near Bitlis, honoured as Bediuzzaman, “wonder of the age”. Taken prisoner on the Caucasus front in 1916, he was held at Kostroma in Russia until he escaped in 1918. Under the Turkish Republic he spent decades in exile and prison, and wrote most of the Risale-i Nur during eight years at Barla. Its reading circles grew into a large movement. He died in Urfa in 1960.",
    works: [["Risale-i Nur", "The epistles of light, a commentary on faith of over five thousand pages"], ["Sözler", "The words, the first part of the collection"], ["Mektubat", "The letters"]] },
  { id: "ibn-ashur", name: "Muhammad al-Tahir ibn Ashur", short: "Ibn Ashur", ar: "محمد الطاهر بن عاشور", b: 1879, d: 1973, lane: "quran", also: ["law"], schools: ["Maliki"], places: ["tunis"],
    text: "Maliki scholar of Tunis and rector of the Zaytuna mosque-university. His Qur’an commentary took nearly forty years, and his treatise on the objectives of the Law (1946) revived al-Shatibi’s approach.",
    works: [["al-Tahrir wa’l-tanwir", "Verification and enlightenment"], ["Maqasid al-shari’a al-islamiyya", "The objectives of Islamic law"]] },
  { id: "abd-al-raziq", name: "Ali Abd al-Raziq", short: "Ali Abd al-Raziq", ar: "علي عبد الرازق", b: 1888, d: 1966, lane: "law", places: ["cairo", "oxford", "cairo"],
    text: "Egyptian al-Azhar scholar and judge. In Islam and the Foundations of Governance (1925), written after the caliphate was abolished, he argued that the caliphate is not a religious duty. Al-Azhar’s council stripped him of his title in response.",
    works: [["al-Islam wa usul al-hukm", "Islam and the foundations of governance"]] },
  { id: "tabatabai", name: "Muhammad Husayn Tabataba’i", short: "Tabataba’i", ar: "محمد حسين الطباطبائي", b: 1904, d: 1981, lane: "quran", also: ["philosophy"], schools: ["Twelver"], places: ["tabriz", "najaf", "tabriz", "qom"],
    text: "Twelver scholar and philosopher from Tabriz who taught in Qom. His commentary al-Mizan interprets the Qur’an by the Qur’an itself, and his teaching revived the study of Mulla Sadra.",
    works: [["al-Mizan fi tafsir al-Qur’an", "The balance, on interpreting the Qur’an"], ["Bidayat al-hikma", "The beginning of philosophy"]] },
  { id: "fazlur-rahman", name: "Fazlur Rahman", short: "Fazlur Rahman", ar: "فضل الرحمن", b: 1919, d: 1988, lane: "philosophy", also: ["quran"], places: ["hazara", "lahore", "oxford", "karachi", "chicago"],
    text: "Pakistani scholar who studied at Oxford, directed Pakistan’s Islamic Research Institute, and taught at the University of Chicago. He proposed reading the Qur’an in a “double movement”: from its historical setting to its moral principles, and back to the present.",
    works: [["Major Themes of the Qur’an", "1980"], ["Islam and Modernity", "1982"]] },
  { id: "baqir-sadr", name: "Muhammad Baqir al-Sadr", short: "Baqir al-Sadr", ar: "محمد باقر الصدر", b: 1935, d: 1980, lane: "law", also: ["philosophy"], schools: ["Ja’fari"], places: ["baghdad", "najaf"],
    text: "Twelver jurist and philosopher of Najaf. His Our Philosophy and Our Economy answered Marxism and capitalism from Islamic premises, and his writings on Islamic banking and government were widely studied. He was executed by the Iraqi government in 1980.",
    works: [["Falsafatuna", "Our philosophy"], ["Iqtisaduna", "Our economy"]] }
];
